-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.ete_manuscript_analytic_v2
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.ete_manuscript_analytic_v2 AS SELECT a.*, g.ete_grade_llm, g.has_gross_llm, g.has_micro_llm, g.n_ete_mentions AS llm_ete_mention_count, CASE  WHEN ((a.ete_norm = 'extensive')) THEN ('gross') WHEN ((a.ete_norm IN ('microscopic', 'minimal'))) THEN ('microscopic') WHEN (((a.ete_norm = 'present_unspecified') AND g.has_gross_llm)) THEN ('gross') WHEN (((a.ete_norm = 'present_unspecified') AND g.has_micro_llm)) THEN ('microscopic') WHEN ((a.ete_norm = 'present_unspecified')) THEN ('unspec_remaining') WHEN ((a.ete_norm = 'none')) THEN ('none') ELSE NULL END AS ete_grade_final, CASE  WHEN ((a.ete_norm = 'extensive')) THEN ('structured') WHEN ((a.ete_norm IN ('microscopic', 'minimal'))) THEN ('structured') WHEN (((a.ete_norm = 'present_unspecified') AND g.has_gross_llm)) THEN ('llm_subgrade') WHEN (((a.ete_norm = 'present_unspecified') AND g.has_micro_llm)) THEN ('llm_subgrade') WHEN ((a.ete_norm = 'present_unspecified')) THEN ('unresolved') WHEN ((a.ete_norm = 'none')) THEN ('structured') ELSE NULL END AS ete_grade_source FROM manuscript_workspace.ete_manuscript_analytic_v1 AS a LEFT JOIN manuscript_workspace.ete_llm_grade_patient_v1 AS g ON ((g.research_id = a.research_id));
